() => {
  const canvas = document.createElement("canvas"); canvas.width = 320; canvas.height = 120;
  const drawing = canvas.getContext("2d");
  const frames = [];
  for (let frame = 0; frame < 15; frame++) {
    drawing.fillStyle = "#eef4f8"; drawing.fillRect(0, 0, 320, 120);
    drawing.fillStyle = "#005a9c"; drawing.beginPath(); drawing.arc(20 + frame * 19, 60, 12, 0, Math.PI * 2); drawing.fill();
    frames.push(canvas.toDataURL("image/jpeg", 0.9).split(",")[1]);
  }
  return frames;
}
